$config=[];$file='/var/www/vhosts/mamonestate.com/mamonestate-config.env';foreach(is_readable($file)?file($file,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES):[] as $line){if(str_contains($line,'=')&&!str_starts_with(trim($line),'#')){[$key,$value]=explode('=',$line,2);$config[trim($key)]=trim($value," \t\n\r\0\x0B\"'");}}function db(array $c): PDO {$x=parse_url($c['DATABASE_URL']??'');if(!$x)throw new RuntimeException('Veritabanı ayarı eksik');return new PDO(sprintf('pgsql:host=%s;port=%d;dbname=%s',$x['host'],$x['port']??5432,ltrim($x['path'],'/')),urldecode($x['user']??''),urldecode($x['pass']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}
try{$id=filter_var($_POST['regionId']??null,FILTER_VALIDATE_INT);if(!$id||empty($config['DEEPSEEK_API_KEY']))throw new RuntimeException('Bölge veya DeepSeek anahtarı eksik');$pdo=db($config);$s=$pdo->prepare('select name,province,content_title,description,attractions,seo_title,seo_description,seo_keywords from regions where id=?');$s->execute([$id]);$region=$s->fetch(PDO::FETCH_ASSOC);if(!$region)throw new RuntimeException('Bölge bulunamadı');$prompt="Aşağıdaki Türkçe emlak bölgesi içeriğini en, de, ru, ar ve fr dillerine doğal, profesyonel ve SEO uyumlu şekilde çevir. Özel yer adlarını koru, bilgi ekleme. Her dilde seoTitle 70, seoDescription 170 karakteri geçmesin. Yalnızca {\"translations\":{\"en\":{\"contentTitle\":\"\",\"description\":\"\",\"attractions\":[],\"seoTitle\":\"\",\"seoDescription\":\"\",\"seoKeywords\":\"\"}}} yapısında tüm 5 dili içeren JSON döndür. Türkçe veri: ".json_encode($region,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$payload=json_encode(['model'=>$config['DEEPSEEK_MODEL']??'deepseek-chat','messages'=>[['role'=>'user','content'=>$prompt]],'temperature'=>0.15,'max_tokens'=>6000,'response_format'=>['type'=>'json_object'],'stream'=>false],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$ch=curl_init('https://api.deepseek.com/chat/completions');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>90,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$config['DEEPSEEK_API_KEY']],CURLOPT_POSTFIELDS=>$payload]);$response=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($response===false||$status<200||$status>=300)throw new RuntimeException('DeepSeek çeviri hatası');$content=(string)(json_decode($response,true)['choices'][0]['message']['content']??'');$translations=(json_decode($content,true)['translations']??[]);$pdo->beginTransaction();$upsert=$pdo->prepare('insert into region_translations(region_id,language,content_title,description,attractions,seo_title,seo_description,seo_keywords,ai_model) values(?,?,?,?,?::jsonb,?,?,?,?) on conflict(region_id,language) do update set content_title=excluded.content_title,description=excluded.description,attractions=excluded.attractions,seo_title=excluded.seo_title,seo_description=excluded.seo_description,seo_keywords=excluded.seo_keywords,ai_model=excluded.ai_model,translated_at=now()');$saved=0;foreach(['en','de','ru','ar','fr'] as $lang){$t=$translations[$lang]??null;if(!is_array($t))continue;$upsert->execute([$id,$lang,mb_substr((string)($t['contentTitle']??$region['content_title']),0,220),(string)($t['description']??''),json_encode($t['attractions']??[],JSON_UNESCAPED_UNICODE),mb_substr((string)($t['seoTitle']??''),0,70),mb_substr((string)($t['seoDescription']??''),0,170),mb_substr((string)($t['seoKeywords']??''),0,1000),$config['DEEPSEEK_MODEL']??'deepseek-chat']);$saved++;}$pdo->commit();if($saved!==5)throw new RuntimeException('Bazı diller çevrilemedi');echo json_encode(['ok'=>true,'translated'=>$saved]);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Region translate: '.$e->getMessage());http_response_code(500);echo json_encode(['error'=>'Bölge çevirileri oluşturulamadı.']);}
